INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'illegal', 'adj.', '/ɪˈliːɡl/', '不合法的;违法的', 'Illegal hunting puts many wild animals in danger.', '非法狩猎使许多野生动物处于危险之中。', 'Animals', 1, 0, 'senior', 'wordlist', 'required2', 'U2', 'illegal hunting', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extinct', 'adj.', '/ɪkˈstɪŋkt/', '灭绝的;绝种的;不再存在的', 'Some species would become extinct without help from zoos.', '如果没有动物园的帮助,有些物种就会灭绝。', 'Animals', 2, 0, 'senior', 'wordlist', 'required2', 'U2', 'become extinct', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extinction', 'n.', '/ɪkˈstɪŋkʃn/', '灭绝;绝种', 'Zoos help to save many animals from extinction.', '动物园帮助许多动物免于灭绝。', 'Animals', 3, 0, 'senior', 'wordlist', 'required2', 'U2', 'save from extinction', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'moreover', 'adv.', '/mɔːrˈəʊvə(r)/', '此外;而且', 'Zoos protect animals; moreover, they teach visitors about wildlife.', '动物园保护动物;此外,它们还向游客介绍野生动物。', 'Animals', 4, 0, 'senior', 'wordlist', 'required2', 'U2', 'moreover', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attempt', 'v./n.', '/əˈtempt/', '努力;尝试;试图;企图', 'Many zoos attempt to copy an animal''s natural habitat.', '许多动物园试图仿造动物的自然栖息地。', 'Animals', 5, 0, 'senior', 'wordlist', 'required2', 'U2', 'attempt to do sth', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'material', 'n.', '/məˈtɪəriəl/', '材料;原料;素材', 'A range of materials is used to build a space like the wild.', '人们用多种材料来打造一个像野外的空间。', 'Animals', 6, 0, 'senior', 'wordlist', 'required2', 'U2', 'a range of materials', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exhibition', 'n.', '/ˌeksɪˈbɪʃn/', '展览;展览品;展出', 'Lots of toys are put in exhibitions to keep the animals busy.', '展区里放了许多玩具,好让动物们不无聊。', 'Animals', 7, 0, 'senior', 'wordlist', 'required2', 'U2', 'put in exhibitions', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'typically', 'adv.', '/ˈtɪpɪkli/', '通常;一般;典型地', 'Tropical animals are typically kept in warm tanks.', '热带动物通常被养在温暖的水槽里。', 'Animals', 8, 0, 'senior', 'wordlist', 'required2', 'U2', 'typically housed indoors', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tank', 'n.', '/tæŋk/', '(贮放液体或气体的)箱;槽;罐;水族箱', 'The fish were kept in a clean, heated tank.', '这些鱼被养在干净的、加热过的水族箱里。', 'Animals', 9, 0, 'senior', 'wordlist', 'required2', 'U2', 'a heated tank', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slightly', 'adv.', '/ˈslaɪtli/', '略微;稍微', 'Every zoo has a slightly different way of caring for animals.', '每个动物园照料动物的方式都略有不同。', 'Animals', 10, 0, 'senior', 'wordlist', 'required2', 'U2', 'a slightly different way', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'approach', 'n./v.', '/əˈprəʊtʃ/', '方式;方法;态度;接近', 'This zoo has a kind approach to animal care.', '这家动物园对动物护理有一套善待的方法。', 'Animals', 11, 0, 'senior', 'wordlist', 'required2', 'U2', 'an approach to animal care', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'overall', 'adv.', '/ˌəʊvərˈɔːl/', '总体上;大致上;一般来说', 'Overall, I think good zoos do more good than harm.', '总体上,我认为好的动物园利大于弊。', 'Animals', 12, 0, 'senior', 'wordlist', 'required2', 'U2', 'overall', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'definitely', 'adv.', '/ˈdefɪnətli/', '肯定;确实;一定', 'I will definitely keep visiting good zoos.', '我一定会继续参观优秀的动物园。', 'Animals', 13, 0, 'senior', 'wordlist', 'required2', 'U2', 'definitely continue', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'retire', 'v.', '/rɪˈtaɪə(r)/', '退休;退职', 'After he retired, the old man spent his days caring for a penguin.', '退休后,这位老人每天都在照料一只企鹅。', 'Animals', 14, 0, 'senior', 'wordlist', 'required2', 'U2', 'a retired worker', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'death', 'n.', '/deθ/', '死亡;死;生命的终止', 'The bird was close to death when the old man found it.', '老人发现这只鸟时,它已奄奄一息。', 'Animals', 15, 0, 'senior', 'wordlist', 'required2', 'U2', 'close to death', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'diet', 'n.', '/ˈdaɪət/', '日常饮食;日常食物', 'He fed the penguin a daily diet of fish to make it strong.', '他每天给企鹅喂鱼,让它强壮起来。', 'Animals', 16, 0, 'senior', 'wordlist', 'required2', 'U2', 'a daily diet of fish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'strength', 'n.', '/streŋθ/', '体力;力气;力量', 'Good food helped the penguin get its strength up.', '好的食物帮助企鹅恢复了体力。', 'Animals', 17, 0, 'senior', 'wordlist', 'required2', 'U2', 'get one''s strength up', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'release', 'v./n.', '/rɪˈliːs/', '释放;放走;放出', 'The man tried to release the bird back into the sea.', '那人试图把鸟放回大海。', 'Animals', 18, 0, 'senior', 'wordlist', 'required2', 'U2', 'release into the wild', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nearby', 'adj./adv.', '/ˌnɪəˈbaɪ/', '附近的;在附近', 'He took the penguin to a nearby island in his small boat.', '他用小船把企鹅带到附近的一座岛上。', 'Animals', 19, 0, 'senior', 'wordlist', 'required2', 'U2', 'a nearby island', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'elderly', 'adj.', '/ˈeldəli/', '年纪较大的;上了年纪的', 'The penguin seemed to prefer visiting the elderly man.', '这只企鹅似乎更喜欢去看望那位老人。', 'Animals', 20, 0, 'senior', 'wordlist', 'required2', 'U2', 'the elderly man', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shock', 'n.', '/ʃɒk/', '震惊;惊愕;令人震惊的事', 'The animal''s sudden return came as a happy shock to everyone.', '这只动物的突然归来让所有人又惊又喜。', 'Animals', 21, 0, 'senior', 'wordlist', 'required2', 'U2', 'come as a shock', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'host', 'n.', '/həʊst/', '(待客的)主人;东道主', 'The old man became a kind host to the lonely penguin.', '老人成了这只孤单企鹅热情的主人。', 'Animals', 22, 0, 'senior', 'wordlist', 'required2', 'U2', 'a kind host', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'multiple', 'adj.', '/ˈmʌltɪpl/', '数量多的;多种多样的;多重的', 'There are multiple reasons why we should protect animals.', '我们应当保护动物有多种原因。', 'Animals', 23, 0, 'senior', 'wordlist', 'required2', 'U2', 'multiple reasons', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'variety', 'n.', '/vəˈraɪəti/', '种类;多样;不同种类', 'This park keeps a wide variety of sea animals.', '这座公园养着各种各样的海洋动物。', 'Animals', 24, 0, 'senior', 'wordlist', 'required2', 'U2', 'a variety of species', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slice', 'n./v.', '/slaɪs/', '薄片;一片;切成薄片', 'She gave the seal a slice of fresh fish.', '她给海豹喂了一片新鲜的鱼。', 'Animals', 25, 0, 'senior', 'wordlist', 'required2', 'U2', 'a slice of fish', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'serving', 'n.', '/ˈsɜːvɪŋ/', '(供一个人吃的)一份食物', 'Each animal gets one serving of food at a fixed time.', '每只动物在固定时间吃一份食物。', 'Animals', 26, 0, 'senior', 'wordlist', 'required2', 'U2', 'a serving of food', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'focus', 'v./n.', '/ˈfəʊkəs/', '集中(于);聚焦;焦点', 'Good zoos focus on the health and welfare of their animals.', '好的动物园专注于动物的健康与福利。', 'Animals', 27, 0, 'senior', 'wordlist', 'required2', 'U2', 'focus on', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'facility', 'n.', '/fəˈsɪləti/', '(供特定用途的)场所;设施', 'The injured birds were taken to an animal rescue facility.', '受伤的鸟被送到一处动物救助场所。', 'Animals', 28, 0, 'senior', 'wordlist', 'required2', 'U2', 'a rescue facility', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'strategy', 'n.', '/ˈstrætədʒi/', '策略;计策;行动计划', 'The zoo follows a clear strategy to protect rare species.', '这家动物园遵循一套清晰的策略来保护稀有物种。', 'Animals', 29, 0, 'senior', 'wordlist', 'required2', 'U2', 'a conservation strategy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'phenomenon', 'n.', '/fəˈnɒmɪnən/', '现象', 'Animal migration is a fascinating natural phenomenon.', '动物迁徙是一种迷人的自然现象。', 'Animals', 30, 0, 'senior', 'wordlist', 'required2', 'U2', 'a natural phenomenon', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'species', 'n.', '/ˈspiːʃiːz/', '物种;种类', 'Many endangered species are kept safe in good zoos.', '许多濒危物种在优秀的动物园里得到保护。', 'Animals', 31, 0, 'senior', 'wordlist', 'required2', 'U2', 'endangered species', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'habitat', 'n.', '/ˈhæbɪtæt/', '栖息地;生活环境', 'Zoos try to build spaces like an animal''s natural habitat.', '动物园努力打造像动物自然栖息地的空间。', 'Animals', 32, 0, 'senior', 'wordlist', 'required2', 'U2', 'natural habitat', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wildlife', 'n.', '/ˈwaɪldlaɪf/', '野生动物;野生生物', 'We visited a wildlife park to see animals up close.', '我们去了一座野生动物园近距离观察动物。', 'Animals', 33, 0, 'senior', 'wordlist', 'required2', 'U2', 'a wildlife park', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'endangered', 'adj.', '/ɪnˈdeɪndʒəd/', '濒危的;有灭绝危险的', 'Students learn about endangered animals at the zoo.', '学生们在动物园了解濒危动物。', 'Animals', 34, 0, 'senior', 'wordlist', 'required2', 'U2', 'endangered animals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conservation', 'n.', '/ˌkɒnsəˈveɪʃn/', '保护;保育;(自然资源的)保存', 'Zoos take part in many conservation projects.', '动物园参与许多保护项目。', 'Animals', 35, 0, 'senior', 'wordlist', 'required2', 'U2', 'conservation projects', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hunting', 'n.', '/ˈhʌntɪŋ/', '狩猎;打猎', 'Illegal hunting is a serious threat to wild animals.', '非法狩猎是对野生动物的严重威胁。', 'Animals', 36, 0, 'senior', 'wordlist', 'required2', 'U2', 'illegal hunting', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'welfare', 'n.', '/ˈwelfeə(r)/', '福利;幸福;福祉', 'Every good zoo cares about animal welfare.', '每家好的动物园都关心动物福利。', 'Animals', 37, 0, 'senior', 'wordlist', 'required2', 'U2', 'animal welfare', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'threat', 'n.', '/θret/', '威胁;恐吓;构成威胁的事物', 'Climate change is a real threat to many species.', '气候变化是许多物种面临的真正威胁。', 'Animals', 38, 0, 'senior', 'wordlist', 'required2', 'U2', 'a threat to wildlife', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fund', 'n./v.', '/fʌnd/', '资金;基金;为……提供资金', 'Visiting zoos provides essential funding for conservation.', '参观动物园为保护工作提供了必要的资金。', 'Animals', 39, 0, 'senior', 'wordlist', 'required2', 'U2', 'essential funding', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cruel', 'adj.', '/ˈkruːəl/', '残忍的;残酷的', 'Some people think it is cruel to keep animals in cages.', '有些人认为把动物关在笼子里很残忍。', 'Animals', 40, 0, 'senior', 'wordlist', 'required2', 'U2', 'cruel to animals', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'alternative', 'n./adj.', '/ɔːlˈtɜːnətɪv/', '替代选择;可供选择的', 'For many people, a zoo is a good alternative to the wild.', '对许多人来说,动物园是野外不错的替代选择。', 'Animals', 41, 0, 'senior', 'wordlist', 'required2', 'U2', 'a good alternative', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'educational', 'adj.', '/ˌedʒuˈkeɪʃənl/', '有教育意义的;教育的', 'A trip to the zoo can be both educational and fun.', '去动物园既有教育意义又有趣。', 'Animals', 42, 0, 'senior', 'wordlist', 'required2', 'U2', 'an educational trip', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rescue', 'v./n.', '/ˈreskjuː/', '营救;救援;解救', 'Injured animals are taken to a rescue centre nearby.', '受伤的动物被送往附近的救助中心。', 'Animals', 43, 0, 'senior', 'wordlist', 'required2', 'U2', 'a rescue centre', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harmonious', 'adj.', '/hɑːˈməʊniəs/', '和谐的;融洽的', 'We hope for a harmonious relationship between humans and animals.', '我们希望人类与动物之间有和谐的关系。', 'Animals', 44, 0, 'senior', 'wordlist', 'required2', 'U2', 'a harmonious relationship', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'affectionate', 'adj.', '/əˈfekʃənət/', '充满深情的;亲切的', 'Every year the penguin became more affectionate towards the man.', '每年这只企鹅对老人都变得更加亲昵。', 'Animals', 45, 0, 'senior', 'wordlist', 'required2', 'U2', 'become affectionate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aquarium', 'n.', '/əˈkweəriəm/', '水族馆;养鱼缸', 'The aquarium keeps thousands of sea animals in clean tanks.', '这座水族馆把成千上万的海洋动物养在干净的水槽里。', 'Animals', 46, 0, 'senior', 'wordlist', 'required2', 'U2', 'a large aquarium', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u2.01', '①where(地点先行词,从句缺地点状语)', 'A2', 10, '上外版必修第二册 U2 — 先行词表地点(zoo/park/island/place/habitat 等)、从句不缺主宾(只缺地点状语)时,用关系副词 where(= in/at/on which)。若从句缺主语或宾语则用 which/that,不用 where。', 1, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u2.02', '②when(时间先行词,从句缺时间状语)', 'A2', 10, '上外版必修第二册 U2 — 先行词表时间(day/season/moment/year/time 等)、从句完整(只缺时间状语)时,用关系副词 when(= on/in/during which)。若从句缺主宾则用 which/that。', 2, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u2.03', '③why(原因 reason)+ 介词+which 替代 where/when', 'A2', 10, '上外版必修第二册 U2 — 先行词为 reason、从句缺原因状语时用 why(= for which);正式或介词提前时用「介词+which」(the day on which / the place in which / a means by which);介词后只能用 which,不可用 that/where/when。', 3, 'required2', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.01'), '"This is the zoo ____ I first saw a real giant panda."', 'where', 'which', 'when', 'that', 'A', '先行词 zoo 表地点、从句完整(只缺地点状语)→ where。', 2, 1, 'mcq');
