INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"That is the main reason ____ the rare frogs are kept indoors."', 'why', 'that', 'which', 'where', 'A', '先行词 reason → why。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"Keeping their brains in order is not the only reason ____ animals sleep."', 'that', 'why', 'which', 'where', 'B', '先行词 reason → why。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"Nobody knows the reason ____ the penguin prefers the old man to its own kind."', 'that', 'which', 'why', 'where', 'C', '先行词 reason → why。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"There must be a reason ____ so many tourists travel to see Australian wildlife."', 'that', 'which', 'where', 'why', 'D', '先行词 reason → why。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"These were the bones and shells on ____ the first marks were carved."', 'which', 'that', 'where', 'when', 'A', '介词 on 后只能用 which(不可 that/where)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"The dry season is the time during ____ animals gather around rivers."', 'that', 'which', 'where', 'when', 'B', '介词 during 后用 which(= the time when)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"This is the small boat in ____ he carried the penguin to the island."', 'that', 'when', 'which', 'where', 'C', '介词 in 后指物用 which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"That is the gentle way in ____ a young tiger should be trained."', 'that', 'when', 'where', 'which', 'D', 'the way in which;介词 in 后用 which。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"Caring for a pet is a means by ____ children learn to be responsible."', 'which', 'that', 'when', 'where', 'A', 'a means by which;介词 by 后用 which。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"The zoo is the place at ____ the wounded eagle slowly recovered."', 'that', 'which', 'when', 'where', 'B', '介词 at 后用 which(= the place where)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"11 September 2001 was the day on ____ Salty saved his blind owner."', 'that', 'when', 'which', 'where', 'C', 'the day on which;介词 on 后用 which(= the day when)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"The brush with ____ the cat was gently washed was very soft."', 'that', 'when', 'where', 'which', 'D', '介词 with 后指物用 which。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"That is the island to ____ the penguin was first taken by boat."', 'which', 'that', 'when', 'where', 'A', '介词 to 后指物用 which。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"Hibernation is the way in ____ some animals survive the cold winter."', 'that', 'which', 'when', 'where', 'B', 'the way in which;介词 in 后用 which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"The reason ____ the koala stays in Australia is its special diet."', 'that', 'where', 'why', 'when', 'C', '先行词 reason、缺原因状语 → why。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U2' AND code='s2u2.03'), '"That is the tank in ____ the tropical fish are kept warm all year."', 'that', 'where', 'when', 'which', 'D', 'the tank in which;介词 in 后用 which(= the tank where)。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Zoos: Cruel or Caring?', 'Some people believe that zoos are cruel. They argue that animals have to live in small spaces and can no longer hunt for their own food. An animal kept behind glass leads a very different life from one in the wild. However, for human visitors a trip to the zoo can be an educational experience. When students learn about endangered species and can see them up close, they are more likely to support projects that save these animals from extinction. Zoos are also involved in many conservation projects, and the money from visitors provides important funding for this work. Because of threats such as illegal hunting, there are many species that would disappear if they were not kept safely. Moreover, many zoos attempt to copy an animal''s natural home, using a range of materials to build a space that feels like the wild. Overall, although every zoo is slightly different, a good zoo can be both caring and useful.', '议论·动物园到底是残忍还是关爱', 159, '[{"q":"Why do some people think zoos are cruel?","answer":"A","options":["They are kept in small areas and can no longer catch their own food.","Animals are given too much food.","Animals are released too quickly.","Animals are never shown to visitors."],"explanation":"原文 ''animals have to live in small spaces and can no longer hunt'' 的转述。"},{"q":"How can a visit to the zoo help endangered animals?","answer":"B","options":["It makes the animals stronger overnight.","Visitors are more willing to support projects that protect them.","It sends the animals straight back to the wild.","It ends all illegal hunting at once."],"explanation":"原文 ''more likely to support projects… save these animals from extinction'' 的转述。"},{"q":"What is the writer''s overall attitude towards good zoos?","answer":"A","options":["A well-run zoo can be caring as well as useful.","They are completely useless.","They should all be closed.","They only care about making money."],"explanation":"末句 ''a good zoo can be both caring and useful'' 的转述。"}]'::jsonb, '[{"word":"cruel","cn":"残忍的"},{"word":"endangered","cn":"濒危的"},{"word":"conservation","cn":"保护"},{"word":"funding","cn":"资金"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Friends Reunited', 'In 2011, a retired bricklayer named Joao found a small penguin lying close to death on his local beach in Brazil. He gently cleaned the oil off the bird''s feathers and fed him a daily diet of fish to get his strength up. He named the penguin Dindim. A week later, Joao tried to release Dindim back into the sea, but the bird simply would not leave. He even took Dindim by boat to a nearby island, yet later that day the penguin was back in his backyard. In the end Dindim stayed for eleven months before he disappeared. To everyone''s surprise, he returned the next summer, and he has kept coming back every year since. It is believed that Dindim prefers visiting the elderly man to migrating with other penguins. Joao says he loves the penguin like his own child, and he is sure that Dindim loves him too. Who said there was no good news left in the world?', '记叙·企鹅丁丁与退休老人的友谊', 161, '[{"q":"What did Joao do soon after finding the weak penguin?","answer":"B","options":["He sold it at the market.","He cleaned its feathers and fed it fish.","He left it on the rocks.","He sent it to a city zoo."],"explanation":"原文 ''cleaned the oil off the bird''s feathers and fed him a daily diet of fish'' 的转述。"},{"q":"What happened when Joao tried to set Dindim free?","answer":"C","options":["The penguin flew far away at once.","The penguin attacked the boat.","The penguin refused to leave and came back.","The penguin was never seen again."],"explanation":"原文 ''would not leave… was back in his backyard'' 的转述。"},{"q":"Why does Dindim keep returning, according to the text?","answer":"D","options":["He cannot swim any more.","He is looking for other penguins.","He is afraid of the sea.","He seems to prefer the old man to migrating."],"explanation":"原文 ''prefers visiting the elderly man rather than migrate'' 的转述。"}]'::jsonb, '[{"word":"retire","cn":"退休"},{"word":"diet","cn":"饮食"},{"word":"release","cn":"放走"},{"word":"elderly","cn":"年长的"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Animal Heroes', 'Animals can be heroes too. On 11 September 2001, a guide dog named Salty was at work in one of the towers of the World Trade Centre. As the building began to fall apart around them, Salty calmly led his blind owner and a friend down seventy flights of stairs to safety. Later, both the dog and his owner received special awards for their courage. In another story, a cat saved her owner''s life at home. One night the house slowly began to fill up with a dangerous gas that has no smell. The cat sensed that something was wrong. She started meowing loudly and scratching at objects until her sleepy owner finally woke up and escaped. These two stories remind us that the bond between people and animals can run very deep. When we treat animals with kindness, they often return our care in ways we never expect, and sometimes they even save our lives.', '记叙·动物英雄萨尔蒂与一只猫', 156, '[{"q":"What did the dog Salty do during the disaster?","answer":"A","options":["He guided his blind owner safely down the stairs.","He ran away from the building alone.","He hid under a desk.","He barked but did not move."],"explanation":"原文 ''led his blind owner… down seventy flights of stairs to safety'' 的转述。"},{"q":"How did the cat help her owner?","answer":"B","options":["She opened the front door.","She made noise and woke the owner up.","She called for a doctor.","She put out a fire."],"explanation":"原文 ''meowing loudly and scratching… finally woke up'' 的转述。"},{"q":"What lesson do the two stories teach us?","answer":"C","options":["Animals are always dangerous.","Only dogs can be heroes.","Kindness to animals is often returned.","Pets should never live at home."],"explanation":"末段 ''when we treat animals with kindness, they often return our care'' 的转述。"}]'::jsonb, '[{"word":"hero","cn":"英雄"},{"word":"guide dog","cn":"导盲犬"},{"word":"award","cn":"奖励"},{"word":"bond","cn":"纽带"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How Animals Sleep', 'Do animals sleep the way humans do? Not exactly. We humans usually need around eight hours of sleep each night to keep our brains working well, but animals are very different. Bats, for example, may sleep about twenty hours a day, while giraffes sleep less than two. Keeping the brain healthy is one reason animals rest, but it is not the only one. Some animals, such as bears and turtles, go into a very deep sleep called hibernation. They do this in order to survive seasons when food is hard to find. Before hibernation begins, these animals eat heavily during the months when food is plentiful and build up a thick store of fat. Then they fall asleep and live off that fat through the long cold season, when the weather is freezing and food is limited. Each kind of animal has its own sleeping pattern, shaped over a long time by the place where it lives and the food it can find.', '说明·动物的睡眠与冬眠', 163, '[{"q":"How does the sleep of bats and giraffes differ?","answer":"D","options":["Giraffes sleep about twenty hours a day.","Both sleep exactly eight hours.","Neither of them sleeps at all.","Bats sleep far more hours than giraffes."],"explanation":"原文 ''Bats… sleep about twenty hours… giraffes sleep less than two'' 的转述。"},{"q":"Why do bears and turtles go into hibernation?","answer":"A","options":["To get through seasons with little food.","To grow new fur.","To travel to warmer places.","To stay awake all winter."],"explanation":"原文 ''survive seasons when food is hard to find'' 的转述。"},{"q":"What do animals do just before hibernation?","answer":"B","options":["They stop eating completely.","They eat a lot and store fat.","They look for new homes.","They wake up earlier than usual."],"explanation":"原文 ''eat heavily… build up a thick store of fat'' 的转述。"}]'::jsonb, '[{"word":"hibernation","cn":"冬眠"},{"word":"survive","cn":"存活"},{"word":"plentiful","cn":"充足的"},{"word":"pattern","cn":"模式"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Animals Across Cultures', 'People in different parts of the world do not always see the same animal in the same way. In countries like the United States and Britain, dogs are usually loved as faithful members of the family. They live inside the home, sleep near their owners and join in family life. Yet in some other places, dogs may be viewed quite differently, and people there might treat them as dirty or even as a danger. Cows offer another clear example. In India, the cow is greatly respected and honoured, and many people would never harm one. In several other countries, however, the very same animal is mainly seen as a source of meat. These differences are not really about right or wrong. They grow out of long history, religion and local custom. Understanding why a culture views an animal in a certain way can help us avoid misunderstanding and show more respect when we travel or make friends from other lands.', '说明·不同文化对动物的看法', 160, '[{"q":"How are dogs usually seen in the US and Britain?","answer":"C","options":["As dirty and dangerous.","Only as working animals outside.","As loved members of the family.","As a common source of meat."],"explanation":"原文 ''loved as faithful members of the family'' 的转述。"},{"q":"What does the example of cows in India show?","answer":"D","options":["Cows are eaten everywhere equally.","Cows are disliked in India.","All cultures treat cows the same way.","The same animal can be honoured in one culture and used for meat in another."],"explanation":"原文 ''In India… respected and honoured… elsewhere… a source of meat'' 的转述。"},{"q":"Why does the writer think these differences are worth understanding?","answer":"A","options":["To avoid misunderstanding and show respect.","To prove one culture is better.","To stop people keeping pets.","To make everyone treat animals the same."],"explanation":"末句 ''help us avoid misunderstanding and show more respect'' 的转述。"}]'::jsonb, '[{"word":"faithful","cn":"忠诚的"},{"word":"respect","cn":"尊重"},{"word":"custom","cn":"风俗"},{"word":"source","cn":"来源"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Feeding Homeless Cats: Helping or Hurting?', 'Recently some homeless cats have begun hanging around our school campus, and students cannot agree on what to do. Sally feels sorry for the thin little cats and wants to bring them food every afternoon. She believes that feeding them is a simple act of kindness, and that it is cruel to walk past a hungry animal and do nothing. Jenny, however, is worried. She loves animals too, but she thinks that regular feeding may bring problems. If the cats learn that there is always food on campus, more and more of them may gather there, and the school could become crowded and dirty. A better answer, some students suggest, might be to contact a local animal rescue centre. Workers there could check the cats'' health, find them safe homes and stop the group from growing too fast. In this way the cats are cared for, but the campus does not turn into an unplanned shelter. The real question is how to be kind in a way that truly helps.', '议论·校园喂流浪猫的利弊', 170, '[{"q":"Why does Sally want to feed the homeless cats?","answer":"B","options":["She wants to keep them as pets at home.","She thinks it is kind and cannot ignore a hungry animal.","She is paid to look after them.","She dislikes the school campus."],"explanation":"原文 ''a simple act of kindness… cruel to walk past a hungry animal'' 的转述。"},{"q":"What is Jenny worried might happen?","answer":"C","options":["The cats will run away forever.","The cats will stop eating.","More cats may gather and the campus may get crowded and dirty.","Students will forget to study."],"explanation":"原文 ''more and more of them may gather… crowded and dirty'' 的转述。"},{"q":"What solution do some students suggest?","answer":"D","options":["Ignore the cats completely.","Take all the cats home.","Build a new zoo on campus.","Contact a rescue centre to check and rehome the cats."],"explanation":"原文 ''contact a local animal rescue centre… find them safe homes'' 的转述。"}]'::jsonb, '[{"word":"homeless","cn":"无家可归的"},{"word":"campus","cn":"校园"},{"word":"rescue","cn":"救助"},{"word":"shelter","cn":"收容所"}]'::jsonb, 2, 'required2', 'U2', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'Adopting a Little Dog', 'Last month my family decided to (1)____ a homeless dog from a local rescue centre. The workers there told us that the little dog had been (2)____ from a cold street, where he was close to (3)____. At first he was shy and afraid, and he would (4)____ in a corner whenever we came near. We were patient and gave him a warm bed and a healthy (5)____ of good food every day. Slowly his (6)____ came back, and he began to wag his tail. Now he is a happy, (7)____ dog who follows me everywhere. He has taught me that every animal (8)____ kindness and a second chance. (9)____, caring for him has made our whole family closer. I will (10)____ keep loving and protecting him.', 127, 2, '[{"q":"1","answer":"A","options":["rescue","sell","throw","lose"],"explanation":"rescue a dog 救助一只狗。"},{"q":"2","answer":"B","options":["sold","saved","lost","bought"],"explanation":"had been saved 被救起。"},{"q":"3","answer":"C","options":["money","noise","death","music"],"explanation":"close to death 濒临死亡。"},{"q":"4","answer":"D","options":["dance","sing","shout","hide"],"explanation":"hide in a corner 躲在角落。"},{"q":"5","answer":"A","options":["serving","ticket","price","noise"],"explanation":"a serving of food 一份食物。"},{"q":"6","answer":"B","options":["price","strength","weather","noise"],"explanation":"strength came back 体力恢复。"},{"q":"7","answer":"C","options":["angry","afraid","affectionate","bored"],"explanation":"affectionate dog 亲昵的狗。"},{"q":"8","answer":"D","options":["sells","breaks","loses","deserves"],"explanation":"deserves kindness 值得善待。"},{"q":"9","answer":"A","options":["Moreover","However","Instead","Otherwise"],"explanation":"Moreover 此外(添加)。"},{"q":"10","answer":"B","options":["hardly","definitely","rarely","never"],"explanation":"definitely keep loving 一定继续爱它。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'A Day at the Ocean World', 'On Sunday our class visited a large (1)____ by the sea. It is home to a wide (2)____ of sea animals, from tiny fish to friendly seals. The animals are kept in clean, well-maintained (3)____ that are filled with fresh sea water. A guide explained that the staff (4)____ on the health and welfare of every creature. Tropical fish, she said, are (5)____ kept in warmer water, much like the (6)____ they come from in the wild. We watched a keeper feed a seal a (7)____ of fresh fish, and it clapped its flippers happily. The visit was both fun and (8)____, because we learned so much about ocean life. (9)____, every zoo or aquarium has a slightly different (10)____ to caring for animals, but this one clearly loved its sea friends.', 132, 2, '[{"q":"1","answer":"C","options":["library","factory","aquarium","market"],"explanation":"aquarium 水族馆。"},{"q":"2","answer":"D","options":["price","noise","ticket","variety"],"explanation":"a wide variety of 各种各样的。"},{"q":"3","answer":"A","options":["tanks","books","boxes","cars"],"explanation":"kept in tanks 养在水槽里。"},{"q":"4","answer":"B","options":["sell","focus","break","lose"],"explanation":"focus on 专注于。"},{"q":"5","answer":"C","options":["rarely","hardly","typically","seldom"],"explanation":"typically kept 通常被养。"},{"q":"6","answer":"D","options":["price","noise","market","habitat"],"explanation":"the habitat 栖息地。"},{"q":"7","answer":"A","options":["slice","song","price","ticket"],"explanation":"a slice of fish 一片鱼。"},{"q":"8","answer":"B","options":["boring","educational","useless","empty"],"explanation":"educational 有教育意义的。"},{"q":"9","answer":"C","options":["However","Instead","Overall","Otherwise"],"explanation":"Overall 总体上。"},{"q":"10","answer":"D","options":["price","noise","ticket","approach"],"explanation":"approach to caring 照料的方式。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'Saving the Giant Panda', 'The giant panda was once close to (1)____, and many people feared it might disappear forever. One big (2)____ to the panda was the loss of the bamboo forests (3)____ it lives. To protect this lovely animal, the country set up special parks and started a clear (4)____ for conservation. Scientists studied the panda''s daily (5)____ and made sure there was plenty of fresh bamboo to eat. They also (6)____ healthy young pandas back into the wild, where they could live freely. (7)____, the number of wild pandas has slowly gone up. This success shows that careful (8)____ projects really can work. There are still many reasons (9)____ we must keep protecting the panda, but the (10)____ news is finally hopeful.', 121, 2, '[{"q":"1","answer":"A","options":["extinction","music","money","noise"],"explanation":"close to extinction 濒临灭绝。"},{"q":"2","answer":"B","options":["song","threat","price","ticket"],"explanation":"a threat to 威胁。"},{"q":"3","answer":"C","options":["which","when","where","why"],"explanation":"the forests where it lives 地点先行词用 where。"},{"q":"4","answer":"D","options":["price","noise","ticket","strategy"],"explanation":"a strategy for conservation 保护策略。"},{"q":"5","answer":"A","options":["diet","price","noise","ticket"],"explanation":"daily diet 日常饮食。"},{"q":"6","answer":"B","options":["sold","released","lost","bought"],"explanation":"released back 放归。"},{"q":"7","answer":"C","options":["However","Instead","Gradually","Otherwise"],"explanation":"Gradually 渐渐地。"},{"q":"8","answer":"D","options":["selling","buying","losing","conservation"],"explanation":"conservation projects 保护项目。"},{"q":"9","answer":"A","options":["why","when","where","which"],"explanation":"reasons why 原因。"},{"q":"10","answer":"B","options":["wrong","overall","empty","late"],"explanation":"the overall news 总体的消息。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'Training a Guide Dog', 'Training a guide dog takes patience and a gentle (1)____. It (2)____ with one small, simple lesson, and the trainer never uses fear. When the young dog does what it is asked, it gets a kind word and a tasty (3)____. These good things are known as positive rewards. Step by (4)____, the lessons become a little harder. The dog learns to lead a blind owner safely (5)____ busy streets and down stairs. There may be (6)____ along the way, but the trainer stays calm and patient. (7)____ months of careful work, the dog can finally be (8)____ to a person who needs it. A good guide dog is more than a helper; it becomes a loyal (9)____. The (10)____ why so many people love these dogs is easy to understand.', 131, 2, '[{"q":"1","answer":"C","options":["price","noise","approach","ticket"],"explanation":"a gentle approach 温和的方式。"},{"q":"2","answer":"D","options":["sells","loses","breaks","begins"],"explanation":"begins with 始于。"},{"q":"3","answer":"A","options":["treat","price","noise","ticket"],"explanation":"a tasty treat 美味奖励。"},{"q":"4","answer":"B","options":["price","step","noise","ticket"],"explanation":"step by step 一步步。"},{"q":"5","answer":"C","options":["behind","below","across","under"],"explanation":"across busy streets 穿过繁忙街道。"},{"q":"6","answer":"D","options":["songs","prices","tickets","problems"],"explanation":"problems along the way 沿途困难。"},{"q":"7","answer":"A","options":["After","Before","Without","Against"],"explanation":"After months 经过数月之后。"},{"q":"8","answer":"B","options":["sold","given","thrown","lost"],"explanation":"given to a person 交给某人。"},{"q":"9","answer":"C","options":["price","noise","friend","ticket"],"explanation":"a loyal friend 忠诚的朋友。"},{"q":"10","answer":"D","options":["price","noise","ticket","reason"],"explanation":"the reason why 原因。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'Bird Watching on Campus', 'Our school started a bird-watching club, and it has quickly become my favourite (1)____. Early in the morning is the time (2)____ the birds are most active and easy to see. We sit quietly near the garden, (3)____ is full of trees and flowers. Through our small telescopes we watch a wide (4)____ of birds come and go. Our teacher says that spring is the (5)____ when many birds fly back to build their nests. We keep a notebook (6)____ we write down what each bird looks like and what it eats. (7)____, we even spotted a rare visitor that does not (8)____ live in our city. Bird watching has taught me to be calm and (9)____. (10)____, I have come to love and respect these small, free creatures.', 129, 2, '[{"q":"1","answer":"A","options":["hobby","price","noise","ticket"],"explanation":"favourite hobby 最爱的爱好。"},{"q":"2","answer":"B","options":["where","when","why","which"],"explanation":"the time when 时间先行词用 when。"},{"q":"3","answer":"C","options":["who","when","which","why"],"explanation":"the garden, which is full 指物作主语用 which。"},{"q":"4","answer":"D","options":["price","noise","ticket","variety"],"explanation":"a wide variety of 各种各样的。"},{"q":"5","answer":"A","options":["season","price","noise","ticket"],"explanation":"the season when 季节。"},{"q":"6","answer":"B","options":["who","where","when","why"],"explanation":"a notebook where we write 地点(抽象)用 where。"},{"q":"7","answer":"C","options":["However","Instead","Once","Otherwise"],"explanation":"Once 有一次。"},{"q":"8","answer":"D","options":["hardly","rarely","seldom","usually"],"explanation":"does not usually live 通常不住。"},{"q":"9","answer":"A","options":["patient","angry","afraid","bored"],"explanation":"be patient 有耐心。"},{"q":"10","answer":"B","options":["However","Overall","Instead","Otherwise"],"explanation":"Overall 总体上。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U2', 'The Wonder of Migration', 'Every year millions of animals travel huge distances in a journey we call (1)____. It is one of the most amazing (2)____ in the natural world. Some birds fly thousands of miles to reach warmer lands (3)____ food is easier to find. They leave in autumn, the (4)____ when the cold weather begins, and return again in spring. Scientists are still trying to understand exactly how the animals find their (5)____ across the sea and sky. One (6)____ why migration matters is that it keeps whole groups of animals alive. (7)____, if the animals could not move, many of them would not (8)____ the harsh winter. Sadly, illegal (9)____ and the loss of safe habitats now make these journeys more dangerous. We must (10)____ protect the wild places these travellers depend on.', 132, 2, '[{"q":"1","answer":"C","options":["price","noise","migration","ticket"],"explanation":"migration 迁徙。"},{"q":"2","answer":"D","options":["prices","tickets","noises","phenomena"],"explanation":"phenomena 现象(复数)。"},{"q":"3","answer":"A","options":["where","who","when","why"],"explanation":"lands where food is found 地点先行词用 where。"},{"q":"4","answer":"B","options":["price","season","noise","ticket"],"explanation":"the season when 季节。"},{"q":"5","answer":"C","options":["price","noise","way","ticket"],"explanation":"find their way 找到路。"},{"q":"6","answer":"D","options":["price","noise","ticket","reason"],"explanation":"one reason why 一个原因。"},{"q":"7","answer":"A","options":["Indeed","However","Instead","Otherwise"],"explanation":"Indeed 的确。"},{"q":"8","answer":"B","options":["sell","survive","break","lose"],"explanation":"survive the winter 熬过冬天。"},{"q":"9","answer":"C","options":["price","noise","hunting","ticket"],"explanation":"illegal hunting 非法狩猎。"},{"q":"10","answer":"D","options":["hardly","rarely","seldom","definitely"],"explanation":"definitely protect 一定保护。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 A Trip to the Zoo', '上外版必修第二册 U2 · dialogue', 3, 'Lucy: Did you enjoy our trip to the zoo today, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Why Protect Endangered Species', '上外版必修第二册 U2 · passage', 2, 'Many animals around the world are now endangered.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Should We Feed the Stray Cat?', '上外版必修第二册 U2 · dialogue', 3, 'Mia: Look at that thin cat by the gate. I want to bring it some food.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 How Animals Sleep', '上外版必修第二册 U2 · passage', 2, 'Animals do not all sleep in the same way.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Training a Guide Dog', '上外版必修第二册 U2 · dialogue', 3, 'Ben: Anna, is it true that you help to train guide dogs?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 A Tip for Animal Lovers', '上外版必修第二册 U2 · passage', 2, 'Here is a simple tip for anyone who loves animals.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Feeding Homeless Cats: Helping or Hurting?(校园喂流浪猫:帮助还是伤害?)', 'An Opinion Paragraph on Feeding Homeless Cats', '近来有些流浪猫常在你们校园出没。请用英语写一篇约80词的观点段落,内容包括:① 清楚表明你的观点(支持还是反对在校园喂流浪猫);② 给出一到两条理由或事实;③ 提出一个更妥当的做法(如联系动物救助中心)。注意:用 moreover、however、as a result 等衔接词把句子连起来,代词指代清楚。', 'Some homeless cats often appear on your campus. Write an opinion paragraph (about 80 words) including: 1) a clear statement of your opinion (for or against feeding homeless cats on campus); 2) one or two reasons or facts; 3) a better way to deal with the problem (e.g. contacting an animal rescue centre). Use cohesive devices such as moreover, however and as a result, and make your pronouns clear.', '["清楚表明观点(In my opinion … / I believe …)","给出理由或事实(One reason is … / Moreover …)","提出更妥当的做法(A better way is to … / Instead, we could …)","用衔接词连句、代词指代清楚"]'::jsonb, 70, 100, 'In my opinion, simply feeding homeless cats on campus is not the best way to help them. It is true that the thin cats look hungry, and walking past them feels cruel. However, if students feed the cats every day, more and more of them may gather, and the campus could become crowded and dirty. As a result, both the cats and the students might suffer. A better way is to contact a local animal rescue centre. The workers there can check the cats'' health and find them safe homes. In this way, we are truly kind to the animals.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In my opinion, simply feeding homeless cats on campus is not the best way to help them.","However, if students feed the cats every day, more and more of them may gather.","A better way is to contact a local animal rescue centre that can find them safe homes.","In this way, we are truly kind to the animals."]'::jsonb, '[{"wrong":"More and more cats may gathers.","correct":"More and more cats may gather.","note":"情态动词 may 后用动词原形,不加 s。"},{"wrong":"It is a centre where can check the cats.","correct":"It is a centre where the workers can check the cats.","note":"where 引导的从句不缺主语,需补出主语 the workers。"},{"wrong":"The reason why is the campus get dirty.","correct":"The reason why we worry is that the campus gets dirty.","note":"reason why 后的从句要完整(主谓齐全),表语用 that 从句。"}]'::jsonb, '【喂流浪猫观点段结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U2', '{"title":"定语从句·关系副词 when / where / why 与「介词+which」速查","intro":"关系副词在从句中作状语(时间/地点/原因),等于「介词+which」。判断口诀:从句缺状语→用关系副词,缺主语/宾语→用关系代词 that/which。介词后只能用 which,不可用 that/where/when。","table":{"headers":["关系词","用法 / 例句 / 等价"],"rows":[["where","地点先行词(zoo/park/island/place):the zoo where = in/at which"],["when","时间先行词(day/season/year/moment):the day when = on/in/during which"],["why","原因(reason):the reason why = for which"],["介词+which","从句缺主宾、或更正式:on which / in which / by which / to which"]]},"specialRules":[{"rule":"从句只缺状语(时间/地点/原因)→ 才用关系副词","mark":"the island where it could swim(缺地点状语)"},{"rule":"从句缺主语/宾语 → 即使先行词是时间/地点也用 that/which","mark":"the penguin that he rescued(缺宾语→that)"},{"rule":"the place where = in/at which;the day when = on/in which;the reason why = for which","mark":"等价替换"},{"rule":"介词后只能用 which,不可用 that/where/when","mark":"the boat in which √ / in that ×"}],"why":["关系副词 = 介词 + which,在从句里充当状语,所以从句的主语、宾语都不缺;一旦主语或宾语缺了,就要换成关系代词 that/which。介词提前到关系词前时,只能配 which。"],"gaokaoPoints":["where/when/why 与 which/that 的判断(看从句缺什么成分:缺状语→副词,缺主宾→代词);语法填空与单选高频。","「介词+which」结构:the day on which / the place in which / a means by which;介词后绝不用 that。"],"examVsReal":[{"exam":"the zoo where I saw the panda(考试/书面)","real":"the zoo I saw the panda in","note":"考试用 where;口语常省略关系词、把介词放句末"},{"exam":"the reason why animals sleep(考试)","real":"the reason animals sleep / the reason that animals sleep","note":"考试用 why;口语里 why 常被省略或用 that"}]}'::jsonb, 'sufe');
